import React, { useEffect, useRef, useState, useMemo, useCallback } from "react";
import ReactorCore from "./ReactorCore";

/**
 * SciFiScanReveal
 * ----------------------------------------------------------------------
 * Sci-fi "HUD access granted / face scan" intro-transition, ~22s @ timeline:
 *   input -> loading -> access_granted -> hud_scan -> flash_transition -> reveal
 *
 * Single-file component. No external animation libs — CSS keyframes for
 * discrete phase UI, Canvas2D (via requestAnimationFrame) for the
 * continuous HUD radar rings / particles / flash / circuit effects.
 *
 * Usage:
 *   <SciFiScanReveal revealMedia="/path/to/photo.jpg" speed={1} />
 *
 * Props:
 *   revealMedia      optional image/video url shown at the very end
 *   revealMediaType  "image" | "video"  (default "image")
 *   speed            overall playback speed multiplier (default 1)
 *   autoStart        if true, tries to start immediately (audio may be
 *                     blocked by the browser autoplay policy — default
 *                     false shows a "TAP TO INITIATE SCAN" start screen)
 *   onComplete       called once the 22s timeline finishes
 */

export interface SciFiScanRevealProps {
  revealMedia?: string;
  revealMediaType?: "image" | "video";
  speed?: number;
  autoStart?: boolean;
  onComplete?: () => void;
  className?: string;
}

type Phase =
  | "idle"
  | "input"
  | "identify"
  | "identify_loading"
  | "password"
  | "access_granted"
  | "hud_scan"
  | "flash_transition"
  | "reveal"
  | "done";

// [start, end] in unscaled seconds, matching the source video timeline (0-22s)
// Matches the reference clip's frame-by-frame timing:
//  0-2s  "PLEASE INPUT..." blinking terminal prompt
//  2-4s  "PLEASE IDENTIFY YOURSELF" + empty bordered field
//  4-6s  "ENTER PASSWORD" + field filling with masked dots
//  6-7s  "ACCESS GRANTED" glitch flash
//  7-15s cyan HUD radar rings spinning up, center glyph glowing in
//  15-19s bloom/flare burst + circuit debris + push-through zoom
//  19-22s fade to dark face reveal
const PHASE_TIMES: Record<Exclude<Phase, "idle" | "done">, [number, number]> = {
  input: [0, 1.5],
  identify: [1.5, 3.5],
  identify_loading: [3.5, 4.5],
  password: [4.5, 6],
  access_granted: [6, 7],
  hud_scan: [7, 15],
  flash_transition: [15, 19],
  reveal: [19, 21.5],
};
const TOTAL_DURATION = 21.5;

// ---------------------------------------------------------------------
// Embedded original audio (am_thanh_goc.mp3, 22s) as a data URI so the
// component is fully self-contained. Placeholder replaced at build time.
// ---------------------------------------------------------------------
const AUDIO_SRC = "data:audio/mpeg;base64,";

function phaseAt(tScaled: number): Phase {
  if (tScaled < 0) return "idle";
  if (tScaled >= TOTAL_DURATION) return "done";
  for (const key of Object.keys(PHASE_TIMES) as Array<keyof typeof PHASE_TIMES>) {
    const [s, e] = PHASE_TIMES[key];
    if (tScaled >= s && tScaled < e) return key;
  }
  return "done";
}

function localT(tScaled: number, phase: Phase): number {
  if (phase === "idle" || phase === "done") return 0;
  const [s, e] = PHASE_TIMES[phase as Exclude<Phase, "idle" | "done">];
  return Math.min(1, Math.max(0, (tScaled - s) / (e - s)));
}

// ---------------------------------------------------------------------
// Deterministic-ish random helpers (computed once, not per-render)
// ---------------------------------------------------------------------
function rand(seed: { v: number }) {
  seed.v = (seed.v * 9301 + 49297) % 233280;
  return seed.v / 233280;
}

function makeParticles(count: number, seed: { v: number }) {
  return Array.from({ length: count }, () => ({
    angle: rand(seed) * Math.PI * 2,
    radius: 0.72 + rand(seed) * 0.32,
    size: 0.8 + rand(seed) * 1.8,
    phase: rand(seed) * Math.PI * 2,
    speed: 0.6 + rand(seed) * 1.4,
  }));
}

function makeBinaryRing(count: number, seed: { v: number }) {
  return Array.from({ length: count }, () => ({
    angle: rand(seed) * Math.PI * 2,
    radius: 0.5 + rand(seed) * 0.14,
    char: rand(seed) > 0.5 ? "1" : "0",
  }));
}

function makeCircuitLines(count: number, seed: { v: number }) {
  return Array.from({ length: count }, () => {
    const y = rand(seed);
    const len = 0.08 + rand(seed) * 0.22;
    const x0 = rand(seed);
    const speed = 0.6 + rand(seed) * 1.2;
    const bend = rand(seed) > 0.5;
    return { y, len, x0, speed, bend };
  });
}

function makeMeshNodes(count: number, seed: { v: number }) {
  return Array.from({ length: count }, () => ({
    x: rand(seed),
    y: rand(seed),
    driftA: rand(seed) * Math.PI * 2,
  }));
}

// ---------------------------------------------------------------------
// Canvas drawing
// ---------------------------------------------------------------------
function drawHudScan(
  ctx: CanvasRenderingContext2D,
  w: number,
  h: number,
  t: number,
  progress: number,
  particles: ReturnType<typeof makeParticles>,
  binaryRing: ReturnType<typeof makeBinaryRing>,
  extraScale: number,
  extraAlpha: number,
  glyphAlpha: number = 0
) {
  const cx = w / 2;
  const cy = h / 2;
  const base = Math.min(w, h) * 0.45 * extraScale; // Adjusted base scale to fit beautifully

  // 0. Background radial glow matching the reference image's deep void
  const bgGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, Math.max(w, h) * 0.7);
  bgGrad.addColorStop(0, `rgba(2, 20, 55, ${extraAlpha})`);
  bgGrad.addColorStop(1, `rgba(0, 0, 0, ${extraAlpha})`);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, w, h);

  ctx.save();
  ctx.globalAlpha = extraAlpha;
  ctx.translate(cx, cy);

  const cyan = "rgba(0, 210, 255, ";
  const cyanBright = "rgba(160, 245, 255, ";
  const PI = Math.PI;

  const drawArc = (r: number, width: number, dash: number[], alpha: number, speed: number, dir: number, isGlow: boolean = false, startAng = 0, endAng = PI * 2) => {
    ctx.save();
    ctx.rotate(t * speed * dir);
    ctx.beginPath();
    ctx.arc(0, 0, base * r, startAng, endAng);
    if (dash.length > 0) ctx.setLineDash(dash);
    ctx.lineWidth = width;
    ctx.strokeStyle = (isGlow ? cyanBright : cyan) + alpha + ")";
    if (isGlow) {
      ctx.shadowColor = "#00d2ff";
      ctx.shadowBlur = width > 5 ? 25 : 12;
    }
    ctx.stroke();
    ctx.restore();
  };

  const drawCurvedText = (text: string, r: number, startAngle: number, charSpacing: number, alpha: number, speed: number, dir: number) => {
    ctx.save();
    ctx.rotate(t * speed * dir);
    ctx.font = `bold ${Math.max(10, base * 0.028)}px "Courier New", monospace`;
    ctx.fillStyle = cyanBright + alpha + ")";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    for (let i = 0; i < text.length; i++) {
      ctx.save();
      const angle = startAngle + i * charSpacing;
      ctx.rotate(angle);
      ctx.translate(base * r, 0);
      ctx.rotate(PI / 2); // Orient text tangentially (curving around)
      ctx.fillText(text[i], 0, 0);
      ctx.restore();
    }
    ctx.restore();
  };

  // 1. Innermost thin solid ring
  drawArc(0.25, 1.5, [], 0.9, 0.1, 1);

  // 2. Inner gauge (thick band made of fine radial dashes)
  drawArc(0.30, 10, [1.5, 4], 0.8, 0.15, 1);

  // 3. Second thin solid ring bounding the gauge
  drawArc(0.35, 1.5, [], 0.9, 0.1, 1);

  // 4. MAIN COMPLEX TRACK (Radius 0.45 to 0.61)
  ctx.save();
  ctx.rotate(t * 0.15); // The entire main track rotates together

  // Inner border of the main track
  drawArc(0.45, 1.5, [], 0.6, 0, 1);
  // Outer border of the main track
  drawArc(0.61, 1.5, [], 0.6, 0, 1);

  const trackMid = 0.53;
  const trackWidth = 0.16 * base;

  // Segment A: Left solid glowing block (170° to 270°)
  drawArc(trackMid, trackWidth, [], 1.0, 0, 1, true, 170 * PI / 180, 270 * PI / 180);

  // Segment B: Bottom text arc (70° to 160°)
  const textSpan = 90 * PI / 180;
  const numChars = 38;
  const txt = "000000000000000000000000000000000000000000000";
  drawCurvedText(txt.substring(0, numChars), trackMid, 73 * PI / 180, textSpan / numChars, 0.95, 0, 1);

  // Segment C: Top-Right dotted gauge (280° to 50°) - Note: 280° is equivalent to -80°
  drawArc(trackMid, trackWidth, [2, 6], 0.75, 0, 1, false, -80 * PI / 180, 50 * PI / 180);

  ctx.restore(); // End main track group

  // 5. Middle dashed ring (smooth slow counter-rotation)
  const c5 = 2 * PI * (base * 0.72);
  drawArc(0.72, 2.5, [c5 * 0.05, c5 * 0.02], 0.7, 0.12, -1, true);

  // 6. Outermost thin circle with 4 crosshair ticks
  drawArc(0.85, 1.5, [], 0.5, 0.05, 1);
  // 4 ticks (thick line, large gap)
  const c6 = 2 * PI * (base * 0.85);
  drawArc(0.85, 10, [2, c6 / 4 - 2], 0.9, 0.05, 1, true);

  ctx.restore();
};

function drawFlash(
  ctx: CanvasRenderingContext2D,
  w: number,
  h: number,
  tNorm: number,
  circuitLines: ReturnType<typeof makeCircuitLines>,
  meshNodes: ReturnType<typeof makeMeshNodes>
) {
  const cy = h / 2;

  // horizontal light streak, widening then thinning
  const streakStrength = Math.sin(Math.min(1, tNorm * 1.4) * Math.PI);
  ctx.save();
  const grad = ctx.createLinearGradient(0, cy - h * 0.5, 0, cy + h * 0.5);
  grad.addColorStop(0, "rgba(160,255,255,0)");
  grad.addColorStop(0.5, `rgba(255,255,255,${0.5 * streakStrength})`);
  grad.addColorStop(1, "rgba(160,255,255,0)");
  ctx.fillStyle = grad;
  const bandH = h * (0.03 + streakStrength * 0.28);
  ctx.fillRect(0, cy - bandH / 2, w, bandH);
  ctx.restore();

  // circuit line fragments flying across
  ctx.save();
  ctx.strokeStyle = "rgba(62,232,255,0.55)";
  ctx.lineWidth = 1.4;
  circuitLines.forEach((c) => {
    const progress = (tNorm * c.speed) % 1;
    const x = (c.x0 + progress) % 1;
    const y = c.y * h;
    const xpx = x * w * 1.4 - w * 0.2;
    const len = c.len * w;
    ctx.beginPath();
    ctx.moveTo(xpx, y);
    if (c.bend) {
      ctx.lineTo(xpx + len * 0.6, y);
      ctx.lineTo(xpx + len * 0.6, y + (c.y > 0.5 ? -14 : 14));
      ctx.lineTo(xpx + len, y + (c.y > 0.5 ? -14 : 14));
    } else {
      ctx.lineTo(xpx + len, y);
    }
    ctx.stroke();
    // small rect node
    ctx.strokeRect(xpx + len - 3, y - 3, 6, 6);
  });
  ctx.restore();

  // triangle mesh / constellation network drifting inward
  ctx.save();
  ctx.strokeStyle = "rgba(62,232,255,0.25)";
  ctx.fillStyle = "rgba(160,255,255,0.7)";
  ctx.lineWidth = 0.8;
  const pts = meshNodes.map((n) => {
    const pull = 0.5 + tNorm * 0.5; // drift toward center as tNorm increases
    const x = (n.x + (0.5 - n.x) * (1 - pull) * 0.4) * w;
    const y = (n.y + (0.5 - n.y) * (1 - pull) * 0.4) * h;
    return { x, y };
  });
  for (let i = 0; i < pts.length; i++) {
    for (let j = i + 1; j < pts.length; j++) {
      const dx = pts[i].x - pts[j].x;
      const dy = pts[i].y - pts[j].y;
      const d = Math.hypot(dx, dy);
      if (d < w * 0.16) {
        ctx.beginPath();
        ctx.moveTo(pts[i].x, pts[i].y);
        ctx.lineTo(pts[j].x, pts[j].y);
        ctx.stroke();
      }
    }
  }
  pts.forEach((p) => {
    ctx.beginPath();
    ctx.arc(p.x, p.y, 1.6, 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.restore();
}

// ---------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------
export default function SciFiScanReveal({
  revealMedia,
  revealMediaType = "image",
  speed = 1,
  autoStart = false,
  onComplete,
  className,
}: SciFiScanRevealProps) {
  const [started, setStarted] = useState(autoStart);
  const [phase, setPhase] = useState<Phase>("idle");
  const [inputTyped, setInputTyped] = useState("");
  const [identifyTitleTyped, setIdentifyTitleTyped] = useState("");
  const [accountTextTyped, setAccountTextTyped] = useState("");
  const [passwordTextTyped, setPasswordTextTyped] = useState("");
  const [passwordDots, setPasswordDots] = useState(0);

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const reactorRef = useRef<HTMLDivElement | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);
  const phaseRef = useRef<Phase>("idle");

  const seedRef = useRef({ v: 42 });
  const particles = useMemo(() => makeParticles(46, seedRef.current), []);
  const binaryRing = useMemo(() => makeBinaryRing(34, seedRef.current), []);
  const circuitLines = useMemo(() => makeCircuitLines(9, seedRef.current), []);
  const meshNodes = useMemo(() => makeMeshNodes(16, seedRef.current), []);

  const INPUT_TEXT = "PLEASE INPUT...";
  const IDENTIFY_TEXT = "PLEASE IDENTIFY YOURSELF";
  const ACCOUNT_TEXT = "AMHC-8347-XY";
  const PASSWORD_TEXT = "ENTER PASSWORD";
  const PASSWORD_DOTS_MAX = 16;

  const beginTimeline = useCallback(() => {
    if (started) return;
    setStarted(true);
    const audio = audioRef.current;
    if (audio) {
      audio.currentTime = 0;
      audio.playbackRate = speed;
      audio.play().catch(() => {
        /* autoplay blocked — visuals still run */
      });
    }
  }, [started, speed]);

  useEffect(() => {
    if (autoStart) beginTimeline();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoStart]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Enter") {
        if (!started) {
          beginTimeline();
        } else if (phaseRef.current !== "done") {
          if (rafRef.current) cancelAnimationFrame(rafRef.current);
          if (audioRef.current) {
            audioRef.current.pause();
            audioRef.current.currentTime = 0;
          }
          phaseRef.current = "done";
          setPhase("done");
          if (onComplete) onComplete();
        }
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [started, beginTimeline, onComplete]);

  // main animation loop
  useEffect(() => {
    if (!started) return;
    startTimeRef.current = performance.now();

    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d") || null;

    const resize = () => {
      if (!canvas) return;
      const rect = canvas.parentElement?.getBoundingClientRect();
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      const w = rect ? rect.width : 654;
      const h = rect ? rect.height : 368;
      canvas.width = w * dpr;
      canvas.height = h * dpr;
      canvas.style.width = w + "px";
      canvas.style.height = h + "px";
      ctx?.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    resize();
    window.addEventListener("resize", resize);

    const loop = (now: number) => {
      const realElapsed = (now - (startTimeRef.current || now)) / 1000;
      const tScaled = realElapsed * speed;
      const ph = phaseAt(tScaled);

      if (ph !== phaseRef.current) {
        phaseRef.current = ph;
        setPhase(ph);
        if (ph === "input") setInputTyped("");
        if (ph === "identify") {
          setIdentifyTitleTyped("");
          setAccountTextTyped("");
        }
        if (ph === "password") {
          setPasswordTextTyped("");
          setPasswordDots(0);
        }
      }

      // typing effect for input phase
      if (ph === "input") {
        const lt = localT(tScaled, "input");
        const chars = Math.min(INPUT_TEXT.length, Math.floor(lt * INPUT_TEXT.length * 1.6));
        setInputTyped(INPUT_TEXT.slice(0, chars));
      }

      // typing effect for identify phase
      if (ph === "identify") {
        const lt = localT(tScaled, "identify");
        const titleLt = Math.min(1, lt * 3); // first 33%
        const titleChars = Math.min(IDENTIFY_TEXT.length, Math.floor(titleLt * IDENTIFY_TEXT.length * 1.2));
        setIdentifyTitleTyped(IDENTIFY_TEXT.slice(0, titleChars));

        const accLt = Math.max(0, lt - 0.33) * 1.5; // remaining time
        const accChars = Math.min(ACCOUNT_TEXT.length, Math.floor(accLt * ACCOUNT_TEXT.length * 1.2));
        setAccountTextTyped(ACCOUNT_TEXT.slice(0, accChars));
      }

      // masked-dot fill effect for password phase
      if (ph === "password") {
        const lt = localT(tScaled, "password");
        
        // Type "PASSWORD" text in the first 25% of the phase
        const textLt = Math.min(1, lt * 4);
        const chars = Math.min(PASSWORD_TEXT.length, Math.floor(textLt * PASSWORD_TEXT.length * 1.2));
        setPasswordTextTyped(PASSWORD_TEXT.slice(0, chars));

        // Type dots in the remaining time
        const dotsLt = Math.max(0, lt - 0.25) * 1.33;
        const dots = Math.min(PASSWORD_DOTS_MAX, Math.floor(dotsLt * PASSWORD_DOTS_MAX * 1.3));
        setPasswordDots(dots);
      }

      // canvas rendering
      if (ctx && canvas) {
        const dpr = Math.min(2, window.devicePixelRatio || 1);
        const w = canvas.width / dpr;
        const h = canvas.height / dpr;
        ctx.clearRect(0, 0, w, h);

        if (ph === "hud_scan" || ph === "flash_transition") {
          const hudT = tScaled - PHASE_TIMES.hud_scan[0];
          const hudProgress = Math.min(
            1,
            (tScaled - PHASE_TIMES.hud_scan[0]) /
              (PHASE_TIMES.hud_scan[1] - PHASE_TIMES.hud_scan[0])
          );

          let extraScale = 1 + hudProgress * 0.35;
          let extraAlpha = 1;

          if (ph === "flash_transition") {
            const ft = localT(tScaled, "flash_transition");
            extraScale = 1.35 + ft * ft * 5.5; // push-through zoom blow-up
            extraAlpha = Math.max(0, 1 - ft * 1.15);
          }

          // center glyph fades in ~40% through the scan, holds, fades out by ~78%
          let glyphAlpha = 0;
          if (ph === "hud_scan") {
            if (hudProgress < 0.4) glyphAlpha = 0;
            else if (hudProgress < 0.5) glyphAlpha = (hudProgress - 0.4) / 0.1;
            else if (hudProgress < 0.68) glyphAlpha = 1;
            else if (hudProgress < 0.8) glyphAlpha = 1 - (hudProgress - 0.68) / 0.12;
            else glyphAlpha = 0;
          }

          drawHudScan(ctx, w, h, hudT, hudProgress, particles, binaryRing, extraScale, extraAlpha, glyphAlpha);

          const reactorLayer = reactorRef.current;
          if (reactorLayer) {
            reactorLayer.style.opacity = extraAlpha.toString();
            reactorLayer.style.transform = `translate(-50%, -50%) scale(${extraScale})`;
          }
        } else {
          // If not in hud_scan or flash_transition, make sure it's hidden
          const reactorLayer = reactorRef.current;
          if (reactorLayer) {
            reactorLayer.style.opacity = "0";
          }
        }

        if (ph === "flash_transition") {
          const ft = localT(tScaled, "flash_transition");
          drawFlash(ctx, w, h, ft, circuitLines, meshNodes);
        }
      }

      if (tScaled < TOTAL_DURATION) {
        rafRef.current = requestAnimationFrame(loop);
      } else {
        phaseRef.current = "done";
        setPhase("done");
        onComplete?.();
      }
    };

    rafRef.current = requestAnimationFrame(loop);
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      window.removeEventListener("resize", resize);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [started, speed]);

  const dur = (key: keyof typeof PHASE_TIMES) =>
    (PHASE_TIMES[key][1] - PHASE_TIMES[key][0]) / speed;

  return (
    <div className={"ssr-root" + (className ? " " + className : "")}>
      <style>{`
        .ssr-root {
          position: relative;
          width: 100%;
          aspect-ratio: 654 / 368;
          background: radial-gradient(ellipse at center, #0a1420 0%, #000814 75%);
          overflow: hidden;
          border-radius: 6px;
          font-family: "JetBrains Mono", "Courier New", monospace;
          color: #3EE8FF;
          isolation: isolate;
          user-select: none;
        }
        .ssr-canvas-layer {
          position: absolute;
          inset: 0;
          transition: opacity 1.4s ease;
        }
        .ssr-canvas-layer.hidden { opacity: 0; }

        .ssr-scanlines {
          position: absolute;
          inset: 0;
          pointer-events: none;
          background: repeating-linear-gradient(
            to bottom,
            rgba(255,255,255,0.035) 0px,
            rgba(255,255,255,0.035) 1px,
            rgba(0,0,0,0) 2px,
            rgba(0,0,0,0) 3px
          );
          mix-blend-mode: overlay;
          animation: ssr-flicker 6s infinite;
          z-index: 5;
        }
        .ssr-vignette {
          position: absolute;
          inset: 0;
          pointer-events: none;
          box-shadow: inset 0 0 90px 20px rgba(0,0,0,0.75);
          z-index: 6;
        }
        @keyframes ssr-flicker {
          0%, 92%, 100% { opacity: 1; }
          93% { opacity: 0.85; }
          94% { opacity: 1; }
        }

        .ssr-start {
          position: absolute;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          background: #000814;
          cursor: pointer;
          z-index: 20;
        }
        .ssr-start span {
          padding: 12px 22px;
          border: 1px solid rgba(62,232,255,0.6);
          color: #7FFFFF;
          letter-spacing: 3px;
          font-size: clamp(10px, 2vw, 14px);
          animation: ssr-pulse 1.6s ease-in-out infinite;
          text-shadow: 0 0 8px rgba(62,232,255,0.8);
        }
        @keyframes ssr-pulse {
          0%, 100% { opacity: 0.55; box-shadow: 0 0 4px rgba(62,232,255,0.3); }
          50% { opacity: 1; box-shadow: 0 0 18px rgba(62,232,255,0.7); }
        }

        /* ---- input phase ---- */
        .ssr-terminal {
          position: absolute;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 10;
        }
        .ssr-terminal-text {
          color: rgba(160,255,255,0.9);
          font-size: clamp(12px, 2.6vw, 18px);
          letter-spacing: 2px;
          text-shadow: 0 0 6px rgba(62,232,255,0.7);
        }
        .ssr-cursor {
          display: inline-block;
          width: 0.55em;
          margin-left: 2px;
          background: rgba(62,232,255,0.9);
          animation: ssr-blink 0.9s steps(1) infinite;
        }
        @keyframes ssr-blink { 50% { opacity: 0; } }

        /* ---- loading phase ---- */
        .ssr-loadbox {
          position: absolute;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 10;
        }
        .ssr-loadbox-frame {
          width: 42%;
          height: 6px;
          border: 1px solid rgba(62,232,255,0.5);
          box-shadow: 0 0 10px rgba(62,232,255,0.3);
          position: relative;
          background: rgba(62,232,255,0.05);
        }
        .ssr-loadbox-fill {
          position: absolute;
          top: 0; left: 0; bottom: 0;
          width: 0%;
          background: rgba(62,232,255,0.85);
          box-shadow: 0 0 8px rgba(62,232,255,0.8);
          animation: ssr-fill var(--dur) linear forwards;
        }
        @keyframes ssr-fill { from { width: 0%; } to { width: 100%; } }

        /* ---- identify / password phases ---- */
        .ssr-terminal-stack {
          flex-direction: column;
          gap: 14px;
        }
        .ssr-terminal-text-sm {
          font-size: clamp(10px, 2.2vw, 15px);
          font-weight: bold;
        }
        .ssr-field-frame {
          width: 65%;
          max-width: 260px;
          height: 32px;
          border: 1px solid rgba(255, 107, 53, 0.9);
          box-shadow: 0 0 8px rgba(255, 107, 53, 0.4), inset 0 0 8px rgba(255, 107, 53, 0.2);
          background: rgba(255, 107, 53, 0.05);
          display: flex;
          align-items: center;
          justify-content: flex-start;
          padding-left: 12px;
          box-sizing: border-box;
          position: relative;
        }
        .ssr-field-frame::before {
          content: "";
          position: absolute;
          inset: -4px;
          border: 1px solid rgba(62,232,255,0.3);
          pointer-events: none;
        }
        .ssr-field-text {
          color: rgba(160,255,255,0.95);
          letter-spacing: 2px;
          font-size: clamp(12px, 2.4vw, 16px);
          text-shadow: 0 0 6px rgba(62,232,255,0.8);
          display: flex;
          align-items: center;
        }
        .ssr-field-dots {
          letter-spacing: 4px;
          font-size: clamp(14px, 2.5vw, 18px);
        }

        /* ---- access granted ---- */
        .ssr-granted {
          position: absolute;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 10;
        }
        .ssr-granted-text {
          font-size: clamp(16px, 4.4vw, 30px);
          font-weight: 700;
          letter-spacing: 4px;
          color: #FF6B35;
          text-shadow: 0 0 12px rgba(255,69,0,0.85), 0 0 26px rgba(255,69,0,0.5);
          animation: ssr-glitch var(--dur) steps(2, end) forwards;
        }
        @keyframes ssr-glitch {
          0% { transform: translate(0,0); opacity: 0; }
          8% { opacity: 1; }
          12% { transform: translate(-3px, 1px) skewX(2deg); }
          20% { transform: translate(2px, -1px) skewX(-2deg); }
          28% { transform: translate(-1px, 0); }
          40% { transform: translate(1px, 1px); }
          85% { opacity: 1; transform: translate(0,0); }
          100% { opacity: 0; transform: translate(0,0); }
        }

        /* ---- hud scan labels ---- */
        .ssr-hud-chrome {
          position: absolute;
          inset: 0;
          pointer-events: none;
          z-index: 8;
        }
        .ssr-hud-corner {
          position: absolute;
          width: 22px; height: 22px;
          border: 1.5px solid rgba(62,232,255,0.55);
        }
        .ssr-hud-corner.tl { top: 10px; left: 10px; border-right: none; border-bottom: none; }
        .ssr-hud-corner.tr { top: 10px; right: 10px; border-left: none; border-bottom: none; }
        .ssr-hud-corner.bl { bottom: 10px; left: 10px; border-right: none; border-top: none; }
        .ssr-hud-corner.br { bottom: 10px; right: 10px; border-left: none; border-top: none; }
        .ssr-hud-loading-label {
          position: absolute;
          bottom: 12px;
          left: 16px;
          font-size: 10px;
          letter-spacing: 2px;
          color: rgba(160,255,255,0.85);
          text-shadow: 0 0 6px rgba(62,232,255,0.7);
        }
        .ssr-hud-loading-label::after {
          content: "";
          animation: ssr-dots 1.4s steps(4) infinite;
        }
        @keyframes ssr-dots {
          0% { content: ""; } 25% { content: "."; }
          50% { content: ".."; } 75% { content: "..."; }
        }

        /* ---- reveal ---- */
        .ssr-reveal {
          position: absolute;
          inset: 0;
          z-index: 15;
          background: #000;
          overflow: hidden;
        }
        .ssr-reveal-flash {
          position: absolute;
          inset: 0;
          background: #fff;
          animation: ssr-reveal-flash var(--dur) ease-out forwards;
        }
        @keyframes ssr-reveal-flash {
          0% { opacity: 1; }
          100% { opacity: 0; }
        }
        .ssr-reveal-media {
          position: absolute;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          clip-path: circle(0% at 50% 50%);
          animation: ssr-reveal-clip var(--dur) cubic-bezier(.2,.7,.3,1) forwards;
          animation-delay: calc(var(--dur) * 0.12);
        }
        @keyframes ssr-reveal-clip {
          from { clip-path: circle(0% at 50% 50%); }
          to { clip-path: circle(75% at 50% 50%); }
        }
        .ssr-reveal-media img, .ssr-reveal-media video {
          width: 100%; height: 100%;
          object-fit: cover;
          filter: brightness(0.55) contrast(1.15) saturate(0.9);
        }
        .ssr-reveal-rim {
          position: absolute;
          inset: 0;
          background: linear-gradient(115deg, rgba(62,232,255,0.35) 0%, rgba(62,232,255,0) 38%, rgba(0,0,0,0.5) 100%);
          mix-blend-mode: screen;
          pointer-events: none;
        }
        .ssr-reveal-placeholder {
          width: 46%;
          aspect-ratio: 1;
          border-radius: 50%;
          background: radial-gradient(circle at 38% 35%, rgba(62,232,255,0.35), rgba(0,8,20,0.9) 70%);
          border: 1px solid rgba(62,232,255,0.4);
          display: flex;
          align-items: center;
          justify-content: center;
          text-align: center;
          font-size: 10px;
          letter-spacing: 2px;
          color: rgba(160,255,255,0.75);
          padding: 10px;
        }

        /* ---- intro animations for reactor core ---- */
        .ssr-intro-line {
          position: absolute;
          width: 0px;
          height: 2px;
          background: rgba(62, 232, 255, 0.9);
          box-shadow: 0 0 12px rgba(62, 232, 255, 0.7);
          animation: ssr-intro-line-anim 1.4s 3.2s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
          z-index: 11;
        }
        @keyframes ssr-intro-line-anim {
          0% { width: 4px; height: 4px; border-radius: 50%; opacity: 0; }
          10% { width: 4px; height: 4px; border-radius: 50%; opacity: 1; }
          35% { width: 140px; height: 2px; border-radius: 0; opacity: 1; }
          65% { width: 140px; height: 2px; border-radius: 0; opacity: 1; }
          85% { width: 0px; height: 2px; opacity: 0; }
          100% { width: 0px; height: 2px; opacity: 0; }
        }

        .ssr-intro-circle {
          position: absolute;
          width: 140px;
          height: 140px;
          border-radius: 50%;
          border: 2px solid transparent;
          border-top-color: rgba(62, 232, 255, 0.9);
          border-bottom-color: rgba(62, 232, 255, 0.9);
          opacity: 0;
          box-shadow: 0 0 20px rgba(62,232,255, 0.4), inset 0 0 20px rgba(62,232,255, 0.4);
          animation: ssr-intro-circle-anim 1.2s 4.0s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
          z-index: 10;
        }
        @keyframes ssr-intro-circle-anim {
          0% { transform: scale(0.6) rotate(0deg); opacity: 0; }
          30% { transform: scale(1) rotate(90deg); opacity: 1; }
          70% { transform: scale(1.2) rotate(180deg); opacity: 1; }
          100% { transform: scale(1.5) rotate(270deg); opacity: 0; }
        }

        .ssr-orb-wrapper {
          position: absolute;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          opacity: 0;
          animation: ssr-orb-fade-in 1s 4.8s ease forwards;
        }
        @keyframes ssr-orb-fade-in {
          from { opacity: 0; transform: scale(0.9); }
          to { opacity: 1; transform: scale(1); }
        }
      `}</style>

      {!started && (
        <div className="ssr-start" onClick={beginTimeline}>
          <span>PRESS ENTER TO INITIATE SCAN</span>
        </div>
      )}

      <canvas
        ref={canvasRef}
        className={
          "ssr-canvas-layer" +
          (phase === "hud_scan" || phase === "flash_transition" ? "" : " hidden")
        }
      />

      <div 
        ref={reactorRef}
        className="ssr-reactor-layer"
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: "min(40vh, 280px)",
          height: "min(40vh, 280px)",
          opacity: 0,
          pointerEvents: "none",
          zIndex: 9,
          display: "flex",
          alignItems: "center",
          justifyContent: "center"
        }}
      >
        {(phase === "hud_scan" || phase === "flash_transition") && (
          <>
            <div className="ssr-intro-line" />
            <div className="ssr-intro-circle" />
            <div className="ssr-orb-wrapper">
              <ReactorCore state="working" />
            </div>
          </>
        )}
      </div>

      {phase === "input" && (
        <div className="ssr-terminal">
          <div className="ssr-terminal-text">
            {inputTyped}
            <span className="ssr-cursor">&nbsp;</span>
          </div>
        </div>
      )}

      {phase === "identify" && (
        <div className="ssr-terminal ssr-terminal-stack" key="identify">
          <div className="ssr-terminal-text ssr-terminal-text-sm">
            {identifyTitleTyped}
            {accountTextTyped.length === 0 && <span className="ssr-cursor">&nbsp;</span>}
          </div>
          <div className="ssr-field-frame">
            <div className="ssr-field-text">
              {accountTextTyped}
              {accountTextTyped.length > 0 && <span className="ssr-cursor">&nbsp;</span>}
            </div>
          </div>
        </div>
      )}

      {phase === "identify_loading" && (
        <div className="ssr-terminal ssr-terminal-stack" key="identify_loading">
          <div className="ssr-terminal-text ssr-terminal-text-sm">
            {IDENTIFY_TEXT}
          </div>
          <div className="ssr-field-frame">
            <div className="ssr-field-text">
              {ACCOUNT_TEXT}
            </div>
          </div>
          <div className="ssr-loadbox-frame" style={{ marginTop: '15px' }}>
            <div className="ssr-loadbox-fill" style={{ ["--dur" as any]: `${dur("identify_loading")}s` }} />
          </div>
        </div>
      )}

      {phase === "password" && (
        <div className="ssr-terminal ssr-terminal-stack" key="password">
          <div className="ssr-terminal-text ssr-terminal-text-sm">
            {passwordTextTyped}
            {passwordDots === 0 && <span className="ssr-cursor">&nbsp;</span>}
          </div>
          <div className="ssr-field-frame">
            <div className="ssr-field-text ssr-field-dots">
              {"•".repeat(passwordDots)}
              {passwordDots > 0 && <span className="ssr-cursor">&nbsp;</span>}
            </div>
          </div>
        </div>
      )}

      {phase === "access_granted" && (
        <div className="ssr-granted" key="granted">
          <div
            className="ssr-granted-text"
            style={{ ["--dur" as any]: `${dur("access_granted")}s` }}
          >
            ACCESS GRANTED
          </div>
        </div>
      )}

      {(phase === "hud_scan" || phase === "flash_transition") && (
        <div className="ssr-hud-chrome">
          <div className="ssr-hud-corner tl" />
          <div className="ssr-hud-corner tr" />
          <div className="ssr-hud-corner bl" />
          <div className="ssr-hud-corner br" />
          {phase === "hud_scan" && (
            <div className="ssr-hud-loading-label">LOADING</div>
          )}
        </div>
      )}

      {phase === "reveal" && (
        <div className="ssr-reveal" key="reveal">
          <div
            className="ssr-reveal-flash"
            style={{ ["--dur" as any]: `${dur("reveal") * 0.6}s` }}
          />
          <div
            className="ssr-reveal-media"
            style={{ ["--dur" as any]: `${dur("reveal")}s` }}
          >
            {revealMedia ? (
              revealMediaType === "video" ? (
                <video src={revealMedia} autoPlay muted loop playsInline />
              ) : (
                <img src={revealMedia} alt="reveal" />
              )
            ) : null}
            <div className="ssr-reveal-rim" />
          </div>
        </div>
      )}

      <div className="ssr-scanlines" />
      <div className="ssr-vignette" />

      <audio ref={audioRef} src={AUDIO_SRC} preload="auto" />
    </div>
  );
}
